effect.shader:
void main(){
  vec2 uv = acScreenNorm;
  vec4 src = texture2DCv(inputImg.texture, uv);
  float a = max(src.a, 1e-4);
  vec3 c = src.rgb / a;
  c = pow(c, vec3(1.0 / max(gamma, 0.05)));
  float n = max(steps, 2.0) - 1.0;
  vec3 q = floor(c * n + 0.5) / n;
  vec3 col = mix(c, q, mixAmt);
  gl_FragColor = vec4(col * a, a);
}
